package amrwb

import (
	"crypto/sha256"
	"errors"
	"fmt"
	"testing"

	"github.com/edmonl/talk2text/internal/amrwb/native"
)

func TestDecodeKnownFrame(t *testing.T) {
	size, _ := native.FrameSize(0x04)
	encoded := append([]byte(Magic), 0x04)
	encoded = append(encoded, make([]byte, size-1)...)

	pcm, err := Decode(encoded, 1)
	if err != nil {
		t.Fatal(err)
	}
	if len(pcm) != pcmBytesPerFrame {
		t.Fatalf("decoded PCM length = %d, want %d", len(pcm), pcmBytesPerFrame)
	}

	// Generated by the unmodified opencore-amr 0.1.6 amrwb-dec example.
	const wantSHA256 = "5c89afd3c80ea5a729a668a97579bf81d3cc326d03687ca942b52e5dec1649b9"
	if got := fmt.Sprintf("%x", sha256.Sum256(pcm)); got != wantSHA256 {
		t.Fatalf("decoded PCM SHA-256 = %s, want %s", got, wantSHA256)
	}
}

func TestDecodeAllFrameTypes(t *testing.T) {
	encoded := []byte(Magic)
	frameCount := 0
	for frameType := 0; frameType < 16; frameType++ {
		size, valid := native.FrameSize(byte(frameType << 3))
		if !valid {
			continue
		}
		encoded = append(encoded, byte(frameType<<3)|0x04)
		encoded = append(encoded, make([]byte, size-1)...)
		frameCount++
	}

	pcm, err := Decode(encoded, frameCount)
	if err != nil {
		t.Fatal(err)
	}
	if want := frameCount * pcmBytesPerFrame; len(pcm) != want {
		t.Fatalf("decoded PCM length = %d, want %d", len(pcm), want)
	}
}

func TestDecodeHeaderOnly(t *testing.T) {
	pcm, err := Decode([]byte(Magic), 0)
	if err != nil {
		t.Fatal(err)
	}
	if pcm == nil || len(pcm) != 0 {
		t.Fatalf("decoded PCM = %#v, want non-nil empty slice", pcm)
	}
}

func TestDecodeIgnoresStoragePaddingBits(t *testing.T) {
	pcm, err := Decode(append([]byte(Magic), 0xff), 1)
	if err != nil {
		t.Fatal(err)
	}
	if len(pcm) != pcmBytesPerFrame {
		t.Fatalf("decoded PCM length = %d, want %d", len(pcm), pcmBytesPerFrame)
	}
}

