func TestDecodeRejectsInvalidInput(t *testing.T) {
	tests := []struct {
		name    string
		data    []byte
		wantErr error
	}{
		{
			name:    "empty",
			wantErr: ErrInvalidHeader,
		},
		{
			name:    "wrong header",
			data:    []byte("#!AMR\n"),
			wantErr: ErrInvalidHeader,
		},
		{
			name:    "multichannel header",
			data:    []byte("#!AMR-WB_MC1.0\n"),
			wantErr: ErrInvalidHeader,
		},
		{
			name:    "reserved frame type",
			data:    append([]byte(Magic), byte(10<<3)|0x04),
			wantErr: ErrInvalidFrame,
		},
		{
			name:    "truncated speech frame",
			data:    append([]byte(Magic), 0x04),
			wantErr: ErrInvalidFrame,
		},
		{
			name: "truncated trailing frame",
			data: append(
				append([]byte(Magic), 0x7c),
				0x04,
			),
			wantErr: ErrInvalidFrame,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if _, err := Decode(tt.data, len(tt.data)); !errors.Is(err, tt.wantErr) {
				t.Fatalf("Decode() error = %v, want %v", err, tt.wantErr)
			}
		})
	}
}

func TestDecodeRejectsTooManyFrames(t *testing.T) {
	encoded := append([]byte(Magic), 0x7c, 0x7c)

	if _, err := Decode(encoded, 1); !errors.Is(err, ErrTooLong) {
		t.Fatalf("Decode() error = %v, want %v", err, ErrTooLong)
	}
}

func FuzzDecode(f *testing.F) {
	f.Add([]byte(Magic))
	f.Add(append([]byte(Magic), 0x7c))
	f.Add(append([]byte(Magic), 0x04))
	f.Add([]byte("not AMR-WB"))

	f.Fuzz(func(t *testing.T, data []byte) {
		_, _ = Decode(data, 100)
	})
}
